import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadKeoladeoData(){const e=readFileSync(resolve(__dirname,"../../frontend/keoladeo-national-park-explorer/keoladeo-data.js"),"utf-8");return new Function(e+"\nreturn { KEOLADEO_INFO, WETLAND_HYDROLOGY, FLYWAY_INFO, BIRD_SPECIES, CYCLING_ROUTES, HISTORY_TIMELINE, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadNationalParksData(){const e=readFileSync(resolve(__dirname,"../../frontend/national-parks-explorer/data.js"),"utf-8");return new Function(e+"\nreturn { NATIONAL_PARKS };")()}function loadSearchIndex(){const e=readFileSync(resolve(__dirname,"../../search-index.js"),"utf-8");return new Function("window",e+"\nreturn window.indiaSearchIndex;")({})}describe("Keoladeo National Park Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadKeoladeoData()}),describe("KEOLADEO_INFO metadata",()=>{it("contains correct park metadata and status",()=>{expect(e.KEOLADEO_INFO.id).toBe("keoladeo"),expect(e.KEOLADEO_INFO.name).toBe("Keoladeo National Park"),expect(e.KEOLADEO_INFO.unescoYear).toBe(1985),expect(e.KEOLADEO_INFO.ramsarYear).toBe(1981),expect(e.KEOLADEO_INFO.coordinates.lat).toBeCloseTo(27.1583,2),expect(e.KEOLADEO_INFO.coordinates.lng).toBeCloseTo(77.5222,2)}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.KEOLADEO_INFO.quickStats)).toBe(!0),expect(e.KEOLADEO_INFO.quickStats.length).toBe(6)})}),describe("WETLAND_HYDROLOGY & FLYWAY_INFO",()=>{it("has overview and 4 seasonal cycle phases",()=>{expect(e.WETLAND_HYDROLOGY.overview).toBeDefined(),expect(Array.isArray(e.WETLAND_HYDROLOGY.seasons)).toBe(!0),expect(e.WETLAND_HYDROLOGY.seasons.length).toBe(4)}),it("FLYWAY_INFO contains Siberian Crane history and origin regions",()=>{expect(e.FLYWAY_INFO.name).toContain("Central Asian Flyway"),expect(e.FLYWAY_INFO.siberianCraneStory).toBeDefined(),expect(Array.isArray(e.FLYWAY_INFO.keyOriginRegions)).toBe(!0),expect(e.FLYWAY_INFO.keyOriginRegions.length).toBeGreaterThan(0)})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of bird species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(10)}),it("every bird has required properties and unique id",()=>{const t=["id","name","scientificName","category","status","season","diet","wingspan","image","description"],a=e.BIRD_SPECIES.map(e=>e.id);expect(new Set(a).size).toBe(a.length),e.BIRD_SPECIES.forEach(e=>{t.forEach(t=>{expect(e).toHaveProperty(t),expect(e[t]).toBeTruthy()})})}),it("includes Siberian Crane and Painted Stork",()=>{const t=e.BIRD_SPECIES.find(e=>"siberian-crane"===e.id),a=e.BIRD_SPECIES.find(e=>"painted-stork"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(t.status).toBe("Critically Endangered")})}),describe("CYCLING_ROUTES",()=>{it("contains 4 cycling routes with distances and landmarks",()=>{expect(Array.isArray(e.CYCLING_ROUTES)).toBe(!0),expect(e.CYCLING_ROUTES.length).toBe(4),e.CYCLING_ROUTES.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("distance"),expect(e).toHaveProperty("duration"),expect(Array.isArray(e.highlights)).toBe(!0),expect(e.highlights.length).toBeGreaterThan(0)})})}),describe("HISTORY_TIMELINE & MAP_HOTSPOTS",()=>{it("HISTORY_TIMELINE spans from 1760s Ajan Bund to UNESCO and present",()=>{expect(Array.isArray(e.HISTORY_TIMELINE)).toBe(!0),expect(e.HISTORY_TIMELINE.length).toBeGreaterThanOrEqual(6);const t=e.HISTORY_TIMELINE[0];expect(t.year).toBe("1760s")}),it("MAP_HOTSPOTS has valid percentage coordinates (0-100)",()=>{expect(Array.isArray(e.MAP_HOTSPOTS)).toBe(!0),expect(e.MAP_HOTSPOTS.length).toBeGreaterThanOrEqual(5),e.MAP_HOTSPOTS.forEach(e=>{expect(e.x).toBeGreaterThanOrEqual(0),expect(e.x).toBeLessThanOrEqual(100),expect(e.y).toBeGreaterThanOrEqual(0),expect(e.y).toBeLessThanOrEqual(100)})})}),describe("Landing Page & Search Index Integration",()=>{it("Keoladeo entry in NATIONAL_PARKS has explorerUrl",()=>{const e=loadNationalParksData().NATIONAL_PARKS.find(e=>"keoladeo"===e.id);expect(e).toBeDefined(),expect(e.explorerUrl).toBe("../keoladeo-national-park-explorer/index.html")}),it("Search Index registers Keoladeo National Park Explorer",()=>{const e=loadSearchIndex().find(e=>"Keoladeo National Park Explorer"===e.title);expect(e).toBeDefined(),expect(e.url).toBe("frontend/keoladeo-national-park-explorer/index.html")})})});